import React, { useEffect, useState } from 'react';
import PropTypes from 'prop-types';
import { Enums, VolumeViewport3D, utilities as csUtils } from '@cornerstonejs/core';
import { ImageScrollbar } from '@ohif/ui-next';

function CornerstoneImageScrollbar({
  viewportData,
  viewportId,
  element,
  imageSliceData,
  setImageSliceData,
  scrollbarWidth,
  scrollbarOrientation,
  servicesManager,
}: withAppTypes<{
  element: HTMLElement;
}>) {
  const { cineService, cornerstoneViewportService, panoramicService, viewportGridService } =
    servicesManager.services;

  const [isDentascan, setIsDentascan] = useState(viewportId.startsWith('dentascan'));

  const onImageScrollbarChange = (imageIndex, viewportId) => {
    const viewport = cornerstoneViewportService.getCornerstoneViewport(viewportId);

    const { isCineEnabled } = cineService.getState();

    if (isCineEnabled) {
      // on image scrollbar change, stop the CINE if it is playing
      cineService.stopClip(element, { viewportId });
      cineService.setCine({ id: viewportId, isPlaying: false });
    }

    csUtils.jumpToSlice(viewport.element, {
      imageIndex,
      debounceLoading: true,
    });

    const _isDentascan = viewportId.startsWith('dentascan');
    setIsDentascan(_isDentascan);
    if (viewportId === 'panoramic' || _isDentascan) {
      // Hardcoded for scrollbar in panoramic
      if (_isDentascan) {
        const viewportIds = cornerstoneViewportService.getViewportIds();
        const viewportIndex = viewportIds.findIndex(vpId => vpId === viewportId);
        const middleDentascanViewportIndex = Math.round(viewportIds.length / 2);
        imageIndex += (viewportIndex - middleDentascanViewportIndex) * 2;
      }
      const displaySetUID = viewportGridService.getDisplaySetsUIDsForViewport('axial')[0];
      panoramicService.setDentascanIndex(displaySetUID, imageIndex);
      setImageSliceData({
        imageIndex: imageIndex,
        numberOfSlices: imageSliceData.numberOfSlices,
      });
    }
  };

  useEffect(() => {
    if (!viewportData) {
      return;
    }

    const viewport = cornerstoneViewportService.getCornerstoneViewport(viewportId);

    if (!viewport || viewport instanceof VolumeViewport3D) {
      return;
    }

    try {
      if (viewportId !== 'panoramic') {
        const imageIndex = viewport.getCurrentImageIdIndex();
        const numberOfSlices = viewport.getNumberOfSlices();

        setImageSliceData({
          imageIndex: imageIndex,
          numberOfSlices,
        });
      } else {
        const displaySetUID = viewportGridService.getDisplaySetsUIDsForViewport('axial')[0];
        const panoramicState = panoramicService.getPanoramicState(displaySetUID);
        if (panoramicState) {
          const panoramicWidth = panoramicState.dentascans.length;
          setImageSliceData({
            imageIndex: Math.round(panoramicWidth / 2) - 1,
            numberOfSlices: panoramicWidth,
          });
        }
      }
      setIsDentascan(viewportId.startsWith('dentascan'));
    } catch (error) {
      console.warn(error);
    }
  }, [viewportId, viewportData]);

  useEffect(() => {
    if (!viewportData) {
      return;
    }
    const { viewportType } = viewportData;
    const eventId =
      (viewportType === Enums.ViewportType.STACK && Enums.Events.STACK_VIEWPORT_SCROLL) ||
      (viewportType === Enums.ViewportType.ORTHOGRAPHIC && Enums.Events.VOLUME_NEW_IMAGE) ||
      Enums.Events.IMAGE_RENDERED;

    const updateIndex = event => {
      const viewport = cornerstoneViewportService.getCornerstoneViewport(viewportId);
      if (!viewport || viewport instanceof VolumeViewport3D) {
        return;
      }
      const { imageIndex, newImageIdIndex = imageIndex } = event.detail;
      const numberOfSlices = viewport.getNumberOfSlices();
      // find the index of imageId in the imageIds
      setImageSliceData({
        imageIndex: newImageIdIndex,
        numberOfSlices,
      });
    };

    element.addEventListener(eventId, updateIndex);

    return () => {
      element.removeEventListener(eventId, updateIndex);
    };
  }, [viewportData, element]);

  return (
    !isDentascan && (
      <ImageScrollbar
        orientation={scrollbarOrientation}
        onChange={evt => onImageScrollbarChange(evt, viewportId)}
        max={imageSliceData.numberOfSlices ? imageSliceData.numberOfSlices - 1 : 0}
        height={scrollbarWidth}
        value={imageSliceData.imageIndex || 0}
      />
    )
  );
}

CornerstoneImageScrollbar.propTypes = {
  viewportData: PropTypes.object,
  viewportId: PropTypes.string.isRequired,
  element: PropTypes.instanceOf(Element),
  scrollbarHeight: PropTypes.string,
  scrollbarOrientation: PropTypes.oneOf(['horizontal', 'vertical']),
  imageSliceData: PropTypes.object.isRequired,
  setImageSliceData: PropTypes.func.isRequired,
  servicesManager: PropTypes.object.isRequired,
};

export default CornerstoneImageScrollbar;
